class Solution {
  private int[] a, rank;
  private int ranks;
  private long total;

  public int shadowPairs(int[] nums) {
    int n = nums.length;
    int[] sorted = nums.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    rank = new int[n];
    for (int i = 0; i < n; i++) rank[i] = java.util.Arrays.binarySearch(sorted, 0, m, nums[i]) + 1;
    ranks = m;
    a = nums;
    total = 0;
    solve(0, n - 1);
    return (int) total;
  }

  private void solve(int l, int r) {
    if (l >= r) return;
    int mid = (l + r) >>> 1;
    solve(l, mid);
    solve(mid + 1, r);
    int ln = mid - l + 1, rn = r - mid;
    int[] leftRank = new int[ln], leftLimit = new int[ln];
    java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
    for (int i = mid; i >= l; i--) {
      Integer higher = set.higher(rank[i]);
      leftRank[i - l] = rank[i];
      leftLimit[i - l] = higher == null ? ranks + 1 : higher;
      set.add(rank[i]);
    }
    int[] rightRank = new int[rn], rightFloor = new int[rn];
    set.clear();
    for (int j = mid + 1; j <= r; j++) {
      Integer lower = set.lower(rank[j]);
      rightRank[j - mid - 1] = rank[j];
      rightFloor[j - mid - 1] = lower == null ? 0 : lower;
      set.add(rank[j]);
    }
    Integer[] leftOrder = new Integer[ln], rightOrder = new Integer[rn];
    for (int i = 0; i < ln; i++) leftOrder[i] = i;
    for (int i = 0; i < rn; i++) rightOrder[i] = i;
    java.util.Arrays.sort(leftOrder, (x, y) -> Integer.compare(leftRank[x], leftRank[y]));
    java.util.Arrays.sort(rightOrder, (x, y) -> Integer.compare(rightFloor[x], rightFloor[y]));
    int[] bit = new int[ranks + 2];
    int ptr = 0;
    for (int oi = 0; oi < ln; oi++) {
      int i = leftOrder[oi];
      while (ptr < rn && rightFloor[rightOrder[ptr]] <= leftRank[i]) {
        for (int p = rightRank[rightOrder[ptr]]; p <= ranks; p += p & -p) bit[p]++;
        ptr++;
      }
      int hi = Math.min(leftLimit[i], ranks), lo = leftRank[i];
      if (hi > lo) total += prefix(bit, hi) - prefix(bit, lo);
    }
  }

  private static int prefix(int[] bit, int i) {
    int s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }
}
